const renderCar = (ctx: RenderContext): TemplateResult => {
  const tracker = entityFromConfig(ctx, "ulm_card_vehicle_status_tracker") ?? ctx.entity;
  const energy = entityFromConfig(ctx, "ulm_card_vehicle_status_energy_level");
  const range = entityFromConfig(ctx, "ulm_card_vehicle_status_range");
  const lock = entityFromConfig(ctx, "ulm_card_vehicle_status_lock");
  const home = tracker?.state === "home";
  const locked = lock?.state === "locked" || lock?.state === "off";
  const roundedState = (entity?: HassEntity): string => {
    const value = numeric(entity?.state);
    return value === undefined ? stateLabel(entity) : String(Math.round(value));
  };
  const metricLabel = (entity: HassEntity | undefined, fallback: string): string =>
    [entity?.attributes.unit_of_measurement, fallback].filter(Boolean).join(" ");
  const trackerLabel = tracker?.last_changed
    ? (() => {
      const minutes = Math.max(0, Math.round((Date.now() - new Date(tracker.last_changed).getTime()) / 60_000));
      return minutes < 1 ? "just now" : `${minutes} minute${minutes === 1 ? "" : "s"} ago`;
    })()
    : stateLabel(tracker);
  return ctx.actionSurface("custom-vehicle-status", html`
    <button class="car-hero" aria-label="Open car details"
      @pointerdown=${(event: Event) => event.stopPropagation()}
      @click=${(event: Event) => runControlAction(event, ctx, { action: "more-info" }, tracker?.entity_id)}>
      <span class="car-icon-wrap">${iconBubble(ctx, "mdi:car", "blue")}
        <i class="car-badge tracker ${home ? "is-home" : "is-away"}"><ha-icon .icon=${home ? "mdi:home-variant" : "mdi:road-variant"}></ha-icon></i>
        <i class="car-badge lock ${locked ? "is-locked" : "is-unlocked"}"><ha-icon .icon=${locked ? "mdi:lock" : "mdi:lock-open"}></ha-icon></i>
      </span>
      ${heading(ctx, trackerLabel)}
    </button>
    <div class="car-metrics">
      <span><ha-icon icon="mdi:gas-station"></ha-icon><b>${roundedState(energy)}</b><small>${metricLabel(energy, configured<string>(ctx, "ulm_custom_card_vehicle_status_energy_level") || "Nível de energia")}</small></span>
      <span><ha-icon icon="mdi:map-marker-distance"></ha-icon><b>${roundedState(range)}</b><small>${metricLabel(range, configured<string>(ctx, "ulm_custom_card_vehicle_status_range") || "Alcance")}</small></span>
    </div>
  `);
};

const renderFlower = (ctx: RenderContext): TemplateResult => {
  const plant = entityFromConfig(ctx, "ulm_card_flower_entity") ?? ctx.entity;
  const problem = plant?.state === "problem";
  const definitionFor = (key: FlowerBarKey) => FLOWER_BARS.find((definition) => definition.key === key)!;
  const metrics = flowerBarsForConfig(ctx.config).flatMap((key) => {
    const definition = definitionFor(key);
    const raw = attr(plant, key);
    const info = typeof raw === "object" && raw !== null
      ? raw as Record<string, unknown>
      : undefined;
    const explicitEntity = entityFromConfig(ctx, flowerEntityConfigKey(key));
    const linkedEntityId = typeof info?.sensor === "string"
      ? info.sensor
      : typeof raw === "string" && ctx.hass.states[raw]
        ? raw
        : undefined;
    const linkedEntity = explicitEntity ?? (linkedEntityId ? ctx.hass.states[linkedEntityId] : undefined);
    const plantDeviceClass = String(attr(plant, "device_class") ?? "");
    const primaryMatches = plant?.entity_id.startsWith("sensor.") && (
      plantDeviceClass === key ||
      (key === "moisture" && (!plantDeviceClass || plantDeviceClass === "humidity"))
    );
    const sourceEntity = linkedEntity ?? (primaryMatches ? plant : undefined);
    const value = numeric(sourceEntity?.state) ?? numeric(info?.current) ?? numeric(raw);
    if (value === undefined) return [];
    const minimum = numeric(info?.min) ?? numeric(attr(sourceEntity, "min")) ?? definition.min;
    const maximum = numeric(info?.max) ?? numeric(attr(sourceEntity, "max")) ?? definition.max;
    const percent = Math.max(0, Math.min(100, ((value - minimum) / Math.max(1, maximum - minimum)) * 100));
    const display = sourceEntity ? stateLabel(sourceEntity) : String(value);
    return [{ key, definition, sourceEntity, value, percent, display }];
  });
  return ctx.actionSurface("custom-plant", html`
    <button class="flower-heading" aria-label="Open plant details"
      @pointerdown=${(event: Event) => event.stopPropagation()}
      @click=${(event: Event) => runControlAction(event, ctx, { action: "more-info" }, plant?.entity_id)}>
      ${iconBubble(ctx, problem ? "mdi:alert-circle" : "mdi:flower", problem ? "red" : "green")}
      ${heading(ctx, problem
        ? configured<string>(ctx, "ulm_custom_card_plant_problem") || "Problema"
        : configured<string>(ctx, "ulm_custom_card_plant_correct") || "Correto")}
    </button>
    ${metrics.length ? html`<div class="flower-bars">${metrics.map(({ key, definition, sourceEntity, percent, display }) => {
      const label = `${definition.label}: ${display}`;
      return html`<span data-flower-bar=${key} title=${label} aria-label=${label}>
        <ha-icon .icon=${definition.icon}></ha-icon>
        <i><em style=${`width:${percent}%`}></em></i>
        ${sourceEntity ? html`<output>${display}</output>` : nothing}
      </span>`;
    })}</div>` : nothing}
  `);
};

const renderSpeedtestGauges = (ctx: RenderContext): TemplateResult => {
  const round = configured<boolean>(ctx, "ulm_custom_card_speedtest_round") === true;
  const metric = (
    entityKey: string,
    upstreamKey: string,
    label: string,
    iconName: string,
    colorKey: string,
    fallbackColor: string,
    maxKey: string,
    fallbackMax: number,
    allowRound: boolean,
  ) => {
    const entity = entityFromConfig(ctx, entityKey) ?? entityFromConfig(ctx, upstreamKey);
    const value = numeric(entity?.state);
    const max = Math.max(1, configured<number>(ctx, maxKey) ?? fallbackMax);
    const percent = Math.max(0, Math.min(100, ((value ?? 0) / max) * 100));
    const shownValue = value === undefined ? "—" : allowRound && round ? String(Math.round(value)) : entity!.state;
    const unit = entity?.attributes.unit_of_measurement;
    const color = configuredColor(configured<string>(ctx, colorKey), fallbackColor);
    return html`
      <div class="speedtest-metric" style=${`--speedtest-color:${color};--speedtest-value:${percent}`}>
        <svg class="speedtest-ring" viewBox="0 0 120 100" aria-hidden="true">
          <path class="speedtest-track" pathLength="100" d="M14 83 A50 50 0 1 1 106 83"></path>
          <path class="speedtest-value" pathLength="100" d="M14 83 A50 50 0 1 1 106 83"></path>
        </svg>
        <span class="speedtest-value-copy"><ha-icon .icon=${iconName}></ha-icon><b>${shownValue}${unit ? ` ${String(unit)}` : ""}</b><small>${label}</small></span>
      </div>`;
  };
  return ctx.actionSurface("custom-speedtest-gauges", html`
    <div class="speedtest-three">
      ${metric("download_entity", "ulm_custom_card_speedtest_download_speed_entity", "Download", "mdi:download",
        "ulm_custom_card_speedtest_download_speed_color", "rgb(var(--rgb-yellow, 255, 235, 59))", "ulm_custom_card_speedtest_download_speed_max", 100, true)}
      ${metric("upload_entity", "ulm_custom_card_speedtest_upload_speed_entity", "Upload", "mdi:upload",
        "ulm_custom_card_speedtest_upload_speed_color", "rgb(var(--rgb-blue, 33, 150, 243))", "ulm_custom_card_speedtest_upload_speed_max", 40, true)}
      ${metric("ping_entity", "ulm_custom_card_speedtest_ping_entity", "Ping", "mdi:wan",
        "ulm_custom_card_speedtest_ping_color", "rgb(var(--rgb-green, 76, 175, 80))", "ulm_custom_card_speedtest_ping_max", 85, false)}
    </div>
  `);
};

const renderPollen = (ctx: RenderContext): TemplateResult => {
  const translations: Record<string, Record<string, string>> = {
    en: { none: "None", very_low: "Very low", low: "Low", medium: "Medium", high: "High", very_high: "Very high", tree: "Trees", grass: "Grass", weed: "Weeds" },
    de: { none: "Keine", very_low: "Sehr niedrig", low: "Niedrig", medium: "Mittel", high: "Hoch", very_high: "Sehr hoch", tree: "Bäume", grass: "Gräser", weed: "Kräuter" },
    es: { none: "Ninguno", very_low: "Muy bajo", low: "Bajo", medium: "Medio", high: "Alto", very_high: "Muy alto", tree: "Árboles", grass: "Hierbas", weed: "Malezas" },
    nl: { none: "Geen", very_low: "Zeer laag", low: "Laag", medium: "Gemiddeld", high: "Hoog", very_high: "Extreem hoog", tree: "Bomen", grass: "Grassen", weed: "Kruiden" },
    pl: { none: "Brak", very_low: "Bardzo słabe", low: "Słabe", medium: "Średnie", high: "Wysokie", very_high: "Bardzo wysokie", tree: "Drzewa", grass: "Trawy", weed: "Zioła" },
  };
  const language = translations[(ctx.hass.language ?? "en").split("-")[0]] ?? translations.en;
  const items = [
    {
      entity: linkedState(ctx, "trees_entity"),
      name: configured<string>(ctx, "custom_card_pollen_tree_name"),
      icon: configured<string>(ctx, "custom_card_pollen_tree_icon"),
      kind: "tree",
      fallbackIcon: "mdi:tree",
    },
    {
      entity: linkedState(ctx, "grass_entity"),
      name: configured<string>(ctx, "custom_card_pollen_grass_name"),
      icon: configured<string>(ctx, "custom_card_pollen_grass_icon"),
      kind: "grass",
      fallbackIcon: "mdi:grass",
    },
    {
      entity: linkedState(ctx, "weeds_entity"),
      name: configured<string>(ctx, "custom_card_pollen_weed_name"),
      icon: configured<string>(ctx, "custom_card_pollen_weed_icon"),
      kind: "weed",
      fallbackIcon: "mdi:flower-pollen",
    },
  ];
  const severity = (state?: string): { label: string; color: string; extreme: boolean } => {
    const normalized = state?.toLowerCase() ?? "none";
    const colors: Record<string, string> = {
      none: "rgba(var(--color-grey, 158, 158, 158), 1)",
      very_low: "rgba(var(--color-green, 76, 175, 80), 1)",
      low: "rgb(241, 196, 15)",
      medium: "rgb(243, 156, 18)",
      high: "rgb(231, 76, 60)",
      very_high: "rgba(var(--color-pink, 233, 30, 99), 1)",
    };
    return {
      label: language[normalized] ?? language.none,
      color: colors[normalized] ?? colors.none,
      extreme: normalized === "very_high",
    };
  };
  return ctx.actionSurface("custom-pollen", html`
    <div class="pollen-heading">${heading(ctx, stateLabel(ctx.entity), ctx.descriptor.name)}</div>
    ${items.map((item) => {
      const state = severity(item.entity?.state);
      const name = item.name || item.entity?.attributes.friendly_name || language[item.kind];
      const iconName = item.icon || item.entity?.attributes.icon || item.fallbackIcon;
      return html`<button class="pollen-item" style=${`--pollen:${state.color}`}
        ?disabled=${!item.entity}
        @pointerdown=${(event: Event) => event.stopPropagation()}
        @click=${(event: Event) => item.entity && runControlAction(event, ctx, { action: "more-info" }, item.entity.entity_id)}>
        <span class="pollen-item-icon"><ha-icon .icon=${iconName}></ha-icon>
          ${state.extreme ? html`<span class="pollen-extreme"><ha-icon .icon=${"mdi:exclamation-thick"}></ha-icon></span>` : nothing}
        </span>
        <b>${name}</b><small>${item.entity ? state.label : "Entity unavailable"}</small>
      </button>`;
    })}
  `);
};

const renderGeneric = (ctx: RenderContext): TemplateResult => {
  const active = activeStates.has(ctx.entity?.state ?? "");
  const color = "rgb(var(--rgb-blue, 33, 150, 243))";
  return ctx.actionSurface("ulm-row", html`
    ${sourceIconBubble(ctx, icon(ctx, "mdi:information-outline"), color, active)}
    ${valueThenName(ctx)}
  `, `--source-color:${color}`);
};

const renderBetterThermostat = (ctx: RenderContext): TemplateResult => {
  const current = numeric(attr(ctx.entity, "current_temperature"));
  const target = numeric(attr(ctx.entity, "temperature"));
  const minimum = numeric(attr(ctx.entity, "min_temp")) ?? 5;
  const maximum = numeric(attr(ctx.entity, "max_temp")) ?? 35;
  const step = ctx.config.thermostat_temp_step ??
    numeric(attr(ctx.entity, "target_temp_step")) ??
    0.5;
  const unit = String(
    attr(ctx.entity, "temperature_unit") ??
    attr(ctx.entity, "unit_of_measurement") ??
    "°C",
  );
  const humidityEntity = linkedState(ctx, "humidity_entity");
  const humidity = numeric(humidityEntity?.state) ??
    numeric(attr(ctx.entity, "current_humidity")) ??
    numeric(attr(ctx.entity, "humidity"));
  const windowEntity = linkedState(ctx, "window_sensor");
  const windowState = windowEntity?.state.toLowerCase();
  const windowOpen = ["on", "open", "true"].includes(windowState ?? "") ||
    attr(ctx.entity, "window_open") === true ||
    ["on", "open", "true"].includes(String(attr(ctx.entity, "window_state") ?? "").toLowerCase());
  const batteryEntity = linkedState(ctx, "battery_entity");
  const battery = numeric(batteryEntity?.state) ??
    numeric(attr(ctx.entity, "battery")) ??
    numeric(attr(ctx.entity, "battery_level"));
  const lowBattery = battery !== undefined && battery <= (ctx.config.low_battery_threshold ?? 20);
  const linkedUnavailable = (entityId: string | undefined): boolean => Boolean(
    entityId &&
    (!ctx.hass?.states[entityId] ||
      ["unavailable", "unknown"].includes(ctx.hass.states[entityId].state.toLowerCase())),
  );
  const unavailable = !ctx.entity ||
    ["unavailable", "unknown"].includes(ctx.entity.state.toLowerCase()) ||
    linkedUnavailable(ctx.config.window_sensor) ||
    linkedUnavailable(ctx.config.humidity_entity) ||
    linkedUnavailable(ctx.config.battery_entity);
  const degraded = attr(ctx.entity, "degraded_mode") === true || attr(ctx.entity, "is_degraded") === true;
  const hvacAction = String(attr(ctx.entity, "hvac_action") ?? "").toLowerCase();
  const hvacModes = Array.isArray(attr(ctx.entity, "hvac_modes"))
    ? (attr(ctx.entity, "hvac_modes") as unknown[]).map(String)
    : [];
  const presetMode = String(attr(ctx.entity, "preset_mode") ?? "");
  const presetModes = Array.isArray(attr(ctx.entity, "preset_modes"))
    ? (attr(ctx.entity, "preset_modes") as unknown[]).map(String)
    : [];
  const compact = ctx.config.variant === "compact";
  const controls = ctx.config.show_controls !== false;
  const collapsed = ctx.config.collapsible_controls === true && ctx.entity?.state === "off";
  const modeIcons: Record<string, string> = {
    off: "mdi:power",
    auto: "mdi:autorenew",
    heat: "mdi:fire",
    cool: "mdi:snowflake",
    heat_cool: "mdi:sun-snowflake-variant",
    dry: "mdi:water-percent",
    fan_only: "mdi:fan",
  };
  const modeTone = hvacAction === "heating" || ctx.entity?.state === "heat"
    ? "orange"
    : hvacAction === "cooling" || ctx.entity?.state === "cool"
      ? "blue"
      : ctx.entity?.state === "off" ? "grey" : "green";
  const statuses = [
    unavailable ? ["Connection lost", "mdi:lan-disconnect", "red"] : undefined,
    degraded ? ["Degraded", "mdi:alert-circle-outline", "orange"] : undefined,
    windowOpen ? ["Window open", "mdi:window-open-variant", "blue"] : undefined,
    lowBattery ? [`Battery ${Math.round(battery!)}%`, "mdi:battery-alert-variant-outline", "red"] : undefined,
    hvacAction === "heating" ? ["Heating", "mdi:radiator", "orange"] : undefined,
    hvacAction === "cooling" ? ["Cooling", "mdi:snowflake", "blue"] : undefined,
    presetMode === "eco" ? ["Eco", "mdi:leaf", "green"] : undefined,
  ].filter((status): status is string[] => Boolean(status));
  const setTarget = (event: Event, value: number): void => {
    event.stopPropagation();
    if (!ctx.config.entity || unavailable) return;
    const clamped = Math.max(minimum, Math.min(maximum, value));
    const precision = String(step).split(".")[1]?.length ?? 0;
    const rounded = Number((Math.round(clamped / step) * step).toFixed(precision));
    ctx.service("climate", "set_temperature", {
      entity_id: ctx.config.entity,
      temperature: rounded,
    });
  };
  const modeLabel = (mode: string): string =>
    mode === "fan_only"
      ? "Fan"
      : mode === "heat_cool"
        ? "Heat/Cool"
        : mode.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
  return ctx.actionSurface(`better-thermostat ${compact ? "is-compact" : ""} tone-${modeTone}`, html`
    <div class="better-thermostat-header">
      ${iconBubble(ctx, hvacAction === "heating" ? "mdi:radiator" : "mdi:thermostat", modeTone)}
      ${heading(ctx, current === undefined ? stateLabel(ctx.entity) : `${current}${unit} current`)}
      <span class="better-thermostat-temperature">
        <b>${target === undefined ? "—" : target}${target === undefined ? "" : unit}</b>
        ${ctx.config.show_humidity !== false && humidity !== undefined
          ? html`<small><ha-icon icon="mdi:water-percent" aria-hidden="true"></ha-icon>${Math.round(humidity)}%</small>`
          : nothing}
      </span>
    </div>
    ${ctx.config.show_status !== false && statuses.length
      ? html`<div class="better-thermostat-statuses">
        ${statuses.map(([label, statusIcon, tone]) => html`
          <span class="better-thermostat-status tone-${tone}">
            <ha-icon .icon=${statusIcon} aria-hidden="true"></ha-icon>${label}
          </span>`)}
      </div>`
      : nothing}
    ${controls && ctx.config.show_temperature_control !== false ? html`
      <div class="better-thermostat-target">
        ${button("Decrease target temperature", "mdi:minus", (event) => setTarget(event, (target ?? minimum) - step), unavailable)}
        ${!compact ? html`
          <label>
            <span>Target temperature</span>
            <input type="range" name="target_temperature" min=${String(minimum)} max=${String(maximum)} step=${String(step)}
              .value=${String(target ?? minimum)}
              ?disabled=${unavailable}
              aria-label="Target temperature"
              @pointerdown=${(event: Event) => event.stopPropagation()}
              @click=${(event: Event) => event.stopPropagation()}
              @change=${(event: Event) => setTarget(event, Number((event.target as HTMLInputElement).value))}>
          </label>`
          : html`<span>${target === undefined ? "—" : target}${target === undefined ? "" : unit}</span>`}
        ${button("Increase target temperature", "mdi:plus", (event) => setTarget(event, (target ?? minimum) + step), unavailable)}
      </div>`
      : nothing}
    ${controls && ctx.config.show_hvac_modes !== false && hvacModes.length ? html`
      <div class="better-thermostat-options" aria-label="HVAC modes">
        ${hvacModes.map((mode) => html`
          <button type="button" class=${ctx.entity?.state === mode ? "is-selected" : ""} ?disabled=${unavailable}
            @pointerdown=${(event: Event) => event.stopPropagation()}
            @click=${(event: Event) => {
              event.stopPropagation();
              if (ctx.config.entity && !unavailable) ctx.service("climate", "set_hvac_mode", { entity_id: ctx.config.entity, hvac_mode: mode });
            }}>
            <ha-icon .icon=${modeIcons[mode] ?? "mdi:thermostat"} aria-hidden="true"></ha-icon>
            <span>${modeLabel(mode)}</span>
          </button>`)}
      </div>`
      : nothing}
    ${controls && !collapsed && ctx.config.show_presets !== false && presetModes.length ? html`
      <div class="better-thermostat-options presets" aria-label="Presets">
        ${presetModes.map((preset) => html`
          <button type="button" class=${presetMode === preset ? "is-selected" : ""} ?disabled=${unavailable}
            @pointerdown=${(event: Event) => event.stopPropagation()}
            @click=${(event: Event) => {
              event.stopPropagation();
              if (ctx.config.entity && !unavailable) ctx.service("climate", "set_preset_mode", { entity_id: ctx.config.entity, preset_mode: preset });
            }}>
            <ha-icon .icon=${preset === "eco" ? "mdi:leaf" : preset === "away" ? "mdi:home-export-outline" : preset === "boost" ? "mdi:rocket-launch" : "mdi:home-thermometer"} aria-hidden="true"></ha-icon>
            <span>${preset === "none" ? "Normal" : modeLabel(preset)}</span>
          </button>`)}
      </div>`
      : nothing}
  `);
};

const renderDefaultGraph = (ctx: RenderContext): TemplateResult => {
  const graphColor = configuredColor(
    configured<string>(ctx, "ulm_card_graph_color"),
    "rgb(var(--rgb-red, 244, 67, 54))",
  );
  const iconColor = configuredColor(
    configured<string>(ctx, "ulm_card_graph_icon_color"),
    graphColor,
  );
  return ctx.actionSurface("ulm-default-graph", html`
    <div class="metric-heading">${sourceIconBubble(ctx, icon(ctx, "mdi:chart-line"), iconColor, true)}${valueThenName(ctx)}</div>
    ${sparkline(ctx, true, ctx.entity, graphColor)}
  `);
};

export const renderByFamily = (ctx: RenderContext): TemplateResult => {
  switch (ctx.descriptor.upstreamId) {
    case "card_battery": return renderDefaultBattery(ctx);
    case "card_graph": return renderDefaultGraph(ctx);
    case "card_media_player": return renderMedia(ctx);
    case "custom_card_trash": return renderTrash(ctx);
    case "custom_card_alarm_time": return renderAlarmTimeCard(ctx);
    case "custom_card_roomview": return renderRoomView(ctx);
    case "custom_card_room_overview": return renderRoomOverview(ctx);
    case "custom_card_welcome": return renderWelcome(ctx);
    case "custom_card_washer": return renderWasher(ctx);
    case "custom_card_sun": return renderSunCard(ctx);
    case "custom_card_input_datetime": return renderInputDateTime(ctx);
    case "custom_card_entity_overview": return renderEntityOverview(ctx);
    case "custom_card_internet_speed": return renderInternetSpeed(ctx);
    case "custom_card_weather_metrics": return renderWeatherMetrics(ctx);
    case "custom_card_media_player_sonos": return renderSonos(ctx);
    case "custom_card_more_power_outlet": return renderMorePowerOutlet(ctx);
    case "custom_card_gauge": return renderDualGauge(ctx);
    case "custom_card_printer": return renderPrinter(ctx);
    case "custom_card_nas_metrics": return renderNasMetrics(ctx);
    case "custom_card_tablet": return renderTablet(ctx);
    case "custom_card_pollen_forecast": return renderPollenForecast(ctx);
    case "custom_card_playstation": return renderConsoleCard(ctx);
    case "custom_card_entity_carousel": return renderEntityCarousel(ctx);
    case "custom_card_vehicle_status": return renderCar(ctx);
    case "custom_card_plant": return renderFlower(ctx);
    case "custom_card_speedtest_gauges": return renderSpeedtestGauges(ctx);
    case "custom_card_pollen": return renderPollen(ctx);
    case "custom_card_better_thermostat": return renderBetterThermostat(ctx);
    case "card_room":
      return renderRoom(ctx);
  }
  if (/trash/.test(ctx.descriptor.upstreamId)) return renderScheduleCard(ctx);
  if (/printer/.test(ctx.descriptor.upstreamId)) return renderDeviceStatus(ctx);
  if (/gauge/.test(ctx.descriptor.upstreamId)) return renderGauge(ctx);
  if (/vehicle_status|plant|entity_overview/.test(ctx.descriptor.upstreamId)) {
    return renderDetailCard(ctx, /vehicle_status/.test(ctx.descriptor.upstreamId) ? "mdi:car" : /plant/.test(ctx.descriptor.upstreamId) ? "mdi:flower" : "mdi:view-grid", "purple");
  }
  switch (ctx.descriptor.family) {
    case "scene": return renderScene(ctx);
    case "battery": return renderBattery(ctx);
    case "bar": return renderBarCard(ctx);
    case "energy":
    case "sensor": return renderMetric(ctx);
    case "media": return renderMedia(ctx);
    case "security": return renderSecurity(ctx);
    case "navigation": return renderNavigation(ctx);
    case "control": return renderControl(ctx);
    case "alarm-time": return renderAlarmTime(ctx);
    case "camera": return renderCamera(ctx);
    default: return renderGeneric(ctx);
  }
};
